-- ============================================================================
-- Merchant Risk & Underwriting - sql/setup.sql
-- ----------------------------------------------------------------------------
-- New-merchant underwriting for a fictional payments processor / acquirer:
-- every application gets an explainable 0-100 risk score, an approve / refer /
-- decline decision, a decline reason and a reserve %, cross-referenced by month
-- against a CFPB payment-complaint backdrop.
--
-- FULLY SYNTHETIC. The application book and the CFPB backdrop come from
-- data/generate.py (fixed seed), pasted below between the GENERATED DATA
-- markers, so every run loads identical numbers. To swap in the REAL free CFPB
-- Complaint Database afterwards, run sql/cfpb_live_backdrop.sql.
--
-- Run top to bottom in one Snowsight worksheet. Needs ACCOUNTADMIN (or a role
-- that can create roles, warehouses and databases and grant
-- SNOWFLAKE.CORTEX_USER). Everything else runs as the pack role.
--
-- Creates: role MERCHANT_RISK_ROLE, warehouse SNOWPACK_MERCHANT_RISK_WH
-- (XSMALL, 60 s auto-suspend), database SNOWPACK_MERCHANT_RISK with schema
-- CORE: 4 tables, 4 views, a semantic view, a Cortex Agent, a notes table and a
-- stage for the Streamlit app. Remove it all with sql/cleanup.sql.
-- ============================================================================

-- 0. Least-privilege role ------------------------------------------------------
USE ROLE ACCOUNTADMIN;
CREATE ROLE IF NOT EXISTS MERCHANT_RISK_ROLE
  COMMENT = 'Merchant Risk & Underwriting example: owns the pack objects, nothing else';
SET my_user = CURRENT_USER();
GRANT ROLE MERCHANT_RISK_ROLE TO USER IDENTIFIER($my_user);
GRANT CREATE DATABASE ON ACCOUNT TO ROLE MERCHANT_RISK_ROLE;
GRANT CREATE WAREHOUSE ON ACCOUNT TO ROLE MERCHANT_RISK_ROLE;
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO ROLE MERCHANT_RISK_ROLE;

-- 1. Warehouse, database, schema (owned by the pack role) -----------------------
USE ROLE MERCHANT_RISK_ROLE;
CREATE WAREHOUSE IF NOT EXISTS SNOWPACK_MERCHANT_RISK_WH
  WITH WAREHOUSE_SIZE = 'XSMALL' AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE
  COMMENT = 'Merchant Risk & Underwriting example';
USE WAREHOUSE SNOWPACK_MERCHANT_RISK_WH;
CREATE DATABASE IF NOT EXISTS SNOWPACK_MERCHANT_RISK COMMENT = 'Merchant Risk & Underwriting example (synthetic data)';
CREATE SCHEMA IF NOT EXISTS SNOWPACK_MERCHANT_RISK.CORE COMMENT = 'Merchant Risk & Underwriting Snow Pack';
USE SCHEMA SNOWPACK_MERCHANT_RISK.CORE;

-- 2. Tables ------------------------------------------------------------------
-- The CFPB backdrop is a VIEW after sql/cfpb_live_backdrop.sql; drop either kind.
EXECUTE IMMEDIATE $$ BEGIN DROP VIEW IF EXISTS MERCHANT_RISK_CFPB_BENCHMARK; EXCEPTION WHEN OTHER THEN NULL; END; $$;
EXECUTE IMMEDIATE $$ BEGIN DROP TABLE IF EXISTS MERCHANT_RISK_CFPB_BENCHMARK; EXCEPTION WHEN OTHER THEN NULL; END; $$;

CREATE OR REPLACE TABLE MERCHANT_RISK_CATEGORY (
  category_code STRING, category_name STRING, mcc STRING, base_risk NUMBER(5,1)
) COMMENT = 'Merchant-category dimension (MCC-aligned) with a base risk weight';

CREATE OR REPLACE TABLE MERCHANT_RISK_APPLICATION (
  application_id STRING, merchant_name STRING, mcc STRING, category_code STRING, category_name STRING,
  credit_tier STRING, requested_monthly_volume NUMBER(12,0), years_in_business NUMBER(4,0),
  prior_processor_flag NUMBER(1,0), chargeback_history_bps NUMBER(6,0), month_end DATE
) COMMENT = 'SYNTHETIC: new-merchant underwriting applications. Replace with your own application intake (same columns) to go live.';

CREATE OR REPLACE TABLE MERCHANT_RISK_CFPB_BENCHMARK (
  cfpb_month DATE, complaint_count NUMBER(10,0), pct_monetary_relief NUMBER(6,2), pct_timely_response NUMBER(6,2)
) COMMENT = 'SYNTHETIC monthly CFPB complaint backdrop for payment products. sql/cfpb_live_backdrop.sql replaces it with the REAL free CFPB Complaint Database.';

-- 3. Synthetic data ------------------------------------------------------------
-- BEGIN GENERATED DATA
-- Generated by data/generate.py (seed 20260630). Do not edit by hand.



-- END GENERATED DATA

-- 4. Explainable score: one column per factor (same formula as the original pack)
--    risk_score = base category risk + chargeback bps / 10 + 8 per tier step
--                 - 1.2 per year trading (capped at 15) - 5 if switching from a
--                 prior processor, clamped to 0-100.
CREATE OR REPLACE VIEW MERCHANT_RISK_SCORE_FACTORS
  COMMENT = 'Per-application risk-score factor contributions (explainable 0-100 score).'
AS
SELECT a.application_id,
       c.base_risk                                           AS f_category,
       a.chargeback_history_bps / 10.0                       AS f_chargebacks,
       (CASE a.credit_tier WHEN 'A-Prime' THEN 0 WHEN 'B-NearPrime' THEN 1
                           WHEN 'C-Subprime' THEN 2 ELSE 3 END) * 8 AS f_credit_tier,
       -LEAST(a.years_in_business, 15) * 1.2                 AS f_tenure,
       -a.prior_processor_flag * 5                           AS f_prior_processor,
       LEAST(100, GREATEST(0, ROUND(c.base_risk + a.chargeback_history_bps / 10.0
            + (CASE a.credit_tier WHEN 'A-Prime' THEN 0 WHEN 'B-NearPrime' THEN 1
                                  WHEN 'C-Subprime' THEN 2 ELSE 3 END) * 8
            - LEAST(a.years_in_business, 15) * 1.2 - a.prior_processor_flag * 5, 1))) AS risk_score
FROM MERCHANT_RISK_APPLICATION a
JOIN MERCHANT_RISK_CATEGORY c USING (category_code);

-- 5. Decision book (risk score drives approve / refer / decline) ---------------
CREATE OR REPLACE TABLE MERCHANT_RISK_DECISION
  COMMENT = 'SYNTHETIC: underwriting decisions derived from the risk score (category, chargeback history, tenure, credit tier).'
AS
SELECT a.application_id,
       CASE WHEN f.risk_score < 40 THEN 'approve'
            WHEN f.risk_score < 70 THEN 'refer'
            ELSE 'decline' END AS decision,
       f.risk_score::NUMBER(5,1) AS risk_score,
       CASE WHEN f.risk_score >= 70 AND a.chargeback_history_bps >= 200 THEN 'High chargeback history'
            WHEN f.risk_score >= 70 AND a.years_in_business < 2        THEN 'Thin operating history'
            WHEN f.risk_score >= 70 AND a.category_name = 'Electronics & Appliances' THEN 'High-risk category'
            WHEN f.risk_score >= 70                                    THEN 'Composite risk over threshold'
            ELSE NULL END AS decline_reason,
       (CASE WHEN f.risk_score < 40 THEN ROUND(f.risk_score / 20.0, 2)
             WHEN f.risk_score < 70 THEN ROUND(f.risk_score / 10.0, 2)
             ELSE 0 END)::NUMBER(6,2) AS reserve_pct
FROM MERCHANT_RISK_APPLICATION a
JOIN MERCHANT_RISK_SCORE_FACTORS f USING (application_id);

-- 6. Application-level view the app reads ---------------------------------------
CREATE OR REPLACE VIEW MERCHANT_RISK_BOOK
  COMMENT = 'One row per application with its decision, score, reason, reserve and factor contributions.'
AS
SELECT a.*, d.decision, d.risk_score, d.decline_reason, d.reserve_pct,
       f.f_category, f.f_chargebacks, f.f_credit_tier, f.f_tenure, f.f_prior_processor
FROM MERCHANT_RISK_APPLICATION a
JOIN MERCHANT_RISK_DECISION d USING (application_id)
JOIN MERCHANT_RISK_SCORE_FACTORS f USING (application_id);

-- 7. Wide benchmark view (category x tier x decision x month) + CFPB backdrop ----
--    CFPB columns use MAX so the per-month value is attached non-additively.
CREATE OR REPLACE VIEW MERCHANT_RISK_BENCHMARK
  COMMENT = 'Underwriting portfolio by category/credit tier/decision/month with CFPB complaint backdrop (per-month, non-additive).'
AS
SELECT
  a.category_code, a.category_name, a.credit_tier, d.decision, a.month_end,
  COUNT(*)                                   AS application_count,
  SUM(a.requested_monthly_volume)            AS requested_volume_usd,
  SUM(d.risk_score)                          AS risk_score_sum,
  SUM(d.reserve_pct)                         AS reserve_pct_sum,
  SUM(IFF(d.decision = 'approve', 1, 0))     AS approved_count,
  SUM(IFF(d.decision = 'decline', 1, 0))     AS declined_count,
  SUM(IFF(d.decision = 'refer', 1, 0))       AS referred_count,
  MAX(cf.complaint_count)                    AS cfpb_complaint_count,
  MAX(cf.pct_monetary_relief)                AS cfpb_pct_monetary_relief,
  MAX(cf.pct_timely_response)                AS cfpb_pct_timely_response
FROM MERCHANT_RISK_APPLICATION a
JOIN MERCHANT_RISK_DECISION d USING (application_id)
LEFT JOIN MERCHANT_RISK_CFPB_BENCHMARK cf ON cf.cfpb_month = a.month_end
GROUP BY a.category_code, a.category_name, a.credit_tier, d.decision, a.month_end;

-- 8. Data-source marker ----------------------------------------------------------
CREATE OR REPLACE VIEW MERCHANT_RISK_DATA_SOURCE_INFO AS
SELECT 'synthetic' AS mode,
       'Synthetic application/decision book and synthetic CFPB backdrop (data/generate.py, fixed seed). Run sql/cfpb_live_backdrop.sql to cross-reference the REAL free CFPB Complaint Database.' AS note;

-- 9. Semantic view for Cortex Analyst --------------------------------------------
CREATE OR REPLACE SEMANTIC VIEW MERCHANT_RISK_SV
  TABLES ( mr AS SNOWPACK_MERCHANT_RISK.CORE.MERCHANT_RISK_BENCHMARK
           PRIMARY KEY (category_code, credit_tier, decision, month_end)
           WITH SYNONYMS = ('merchant risk','underwriting','application decisions')
           COMMENT = 'Underwriting applications/decisions by category, credit tier, decision and month with CFPB backdrop' )
  FACTS (
    mr.application_count AS application_count,
    mr.requested_volume_usd AS requested_volume_usd,
    mr.risk_score_sum AS risk_score_sum,
    mr.reserve_pct_sum AS reserve_pct_sum,
    mr.approved_count AS approved_count,
    mr.declined_count AS declined_count,
    mr.referred_count AS referred_count,
    mr.cfpb_complaint_count AS cfpb_complaint_count,
    mr.cfpb_pct_monetary_relief AS cfpb_pct_monetary_relief,
    mr.cfpb_pct_timely_response AS cfpb_pct_timely_response
  )
  DIMENSIONS (
    mr.category_name AS CATEGORY_NAME WITH SYNONYMS = ('merchant category','vertical','segment') COMMENT = 'Merchant category (MCC-aligned)',
    mr.category_code AS CATEGORY_CODE,
    mr.credit_tier AS CREDIT_TIER WITH SYNONYMS = ('tier','risk tier','credit band') COMMENT = 'Applicant credit tier',
    mr.decision AS DECISION WITH SYNONYMS = ('outcome','underwriting decision') COMMENT = 'approve / refer / decline',
    mr.month_end AS MONTH_END WITH SYNONYMS = ('month','period','as of'),
    mr.report_year AS YEAR(month_end) WITH SYNONYMS = ('year')
  )
  METRICS (
    mr.applications AS SUM(mr.application_count) COMMENT = 'Total applications',
    mr.total_requested_volume AS SUM(mr.requested_volume_usd) COMMENT = 'Total requested monthly volume (USD)',
    mr.approval_rate AS SUM(mr.approved_count) / NULLIF(SUM(mr.application_count), 0) COMMENT = 'Approved / total applications',
    mr.decline_rate AS SUM(mr.declined_count) / NULLIF(SUM(mr.application_count), 0) COMMENT = 'Declined / total applications',
    mr.refer_rate AS SUM(mr.referred_count) / NULLIF(SUM(mr.application_count), 0) COMMENT = 'Referred / total applications',
    mr.avg_risk_score AS SUM(mr.risk_score_sum) / NULLIF(SUM(mr.application_count), 0) COMMENT = 'Average risk score (0-100)',
    mr.avg_reserve_pct AS SUM(mr.reserve_pct_sum) / NULLIF(SUM(mr.application_count), 0) COMMENT = 'Average reserve percentage across all applications (declines count as 0)',
    mr.avg_cfpb_complaints AS AVG(mr.cfpb_complaint_count) COMMENT = 'Average monthly CFPB complaints (payment products, non-additive)',
    mr.avg_cfpb_pct_monetary_relief AS AVG(mr.cfpb_pct_monetary_relief) COMMENT = 'Average CFPB pct closed with monetary relief (non-additive)'
  )
  COMMENT = 'Merchant-risk underwriting semantic view (synthetic book vs CFPB complaint backdrop).';

-- 10. Notes table + Cortex Agent ---------------------------------------------------
CREATE TABLE IF NOT EXISTS MERCHANT_RISK_REPORTS (
  run_id STRING DEFAULT UUID_STRING(), subject STRING, draft_md STRING, report_md STRING,
  status STRING, edits_applied INT, residual_hedges INT, edits VARIANT, fact_pack VARIANT,
  model STRING, latency_ms INT,
  created_at TIMESTAMP_NTZ DEFAULT SYSDATE()
) COMMENT = 'Underwriting notes written by AI_COMPLETE and checked by a second AI_COMPLETE pass';

CREATE OR REPLACE AGENT MERCHANT_RISK_AGENT
  COMMENT = 'Merchant Risk & Underwriting agent (Cortex Analyst over MERCHANT_RISK_SV)'
  PROFILE = '{"display_name": "Merchant Risk Agent", "color": "red"}'
  FROM SPECIFICATION
  $$
  models:
    orchestration: auto
  instructions:
    response: 'You are a merchant-underwriting analyst. Use ONLY figures from the Analyst tool. risk_score is 0-100 (higher = riskier). Express USD in $B/$M and rates as percentages. CFPB complaint figures are an external industry backdrop (payment products), not this processor''s own complaints. Never invent numbers. Be concise and cite the month or period. Do not name any real bank, processor or company.'
    orchestration: 'For any application, approval, decline, refer, risk-score, reserve, or CFPB complaint question use the MerchantRisk Analyst tool.'
    sample_questions:
      - question: 'Which merchant categories have the highest decline rate?'
      - question: 'How does the average risk score for C-Subprime compare to A-Prime?'
  tools:
    - tool_spec:
        type: cortex_analyst_text_to_sql
        name: MerchantRisk
        description: 'Underwriting applications/decisions by category, credit tier, decision and month, with a CFPB complaint-intensity backdrop.'
  tool_resources:
    MerchantRisk:
      semantic_view: SNOWPACK_MERCHANT_RISK.CORE.MERCHANT_RISK_SV
      execution_environment:
        type: warehouse
        warehouse: SNOWPACK_MERCHANT_RISK_WH
  $$;

-- 11. Stage for the Streamlit in Snowflake app ----------------------------------------
-- Upload app/ to this stage (README, "Deploy the app in Snowflake"), then run
-- the CREATE STREAMLIT statement shown there.
CREATE STAGE IF NOT EXISTS APP_STAGE DIRECTORY = (ENABLE = TRUE)
  COMMENT = 'Source files for the Merchant Risk & Underwriting Streamlit app';

SELECT decision, COUNT(*) AS applications FROM MERCHANT_RISK_DECISION GROUP BY decision ORDER BY decision;
